import{_ as t,c as i,al as a,o as l}from"./chunks/framework.DCERqlYr.js";const m=JSON.parse('{"title":"Режими польоту","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes/index.md","filePath":"uk/flight_modes/index.md"}'),o={name:"uk/flight_modes/index.md"};function r(s,e,d,_,n,f){return l(),i("div",null,e[0]||(e[0]=[a('<h1 id="режими-польоту" tabindex="-1">Режими польоту <a class="header-anchor" href="#режими-польоту" aria-label="Permalink to &quot;Режими польоту&quot;">​</a></h1><p>Режими польоту забезпечують автопілот підтримку для полегшення ручного польоту транспортного засобу, автоматизацію загальних завдань, таких як зльот та посадка, виконання автономних місій або делегування керування польотом зовнішній системі.</p><p>Для отримання інформації про режими польоту, доступні для певних моделей, дивіться наступні теми:</p><ul><li><a href="./../flight_modes_mc/">Flight Modes (Multicopter)</a></li><li><a href="./../flight_modes_fw/">Flight Modes (Fixed-Wing)</a></li><li><a href="./../flight_modes_vtol/">Режими польоту (VTOL)</a></li><li><a href="./../flight_modes_rover/differential.html">Drive Modes (Differential Rover)</a></li><li><a href="./../flight_modes_rover/ackermann.html">Drive Modes (Ackermann Rover)</a></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Підтеми режимів у цьому розділі містять інформацію, яка є спільною для всіх апаратів, але може не мати відношення до налаштувань за замовчуванням. Як правило, спочатку слід переглянути теми, що стосуються конкретних апаратів, а потім перейти до цих узагальнених тем, коли вони стануть доречними.</p></div>',5)]))}const h=t(o,[["render",r]]);export{m as __pageData,h as default};
